def _gear(cx, cy, r1, r2, teeth=8):
    pts = []
    for i in range(teeth):
        a = 2 * math.pi * i / teeth
        w = math.pi / teeth
        for da, r in ((-0.55 * w, r1), (-0.3 * w, r2), (0.3 * w, r2), (0.55 * w, r1)):
            pts.append((cx + r * math.cos(a + da), cy + r * math.sin(a + da)))
    return pts + [pts[0]]


def _head(cx, cy, r, deg, direction=1, size=11):
    """Arrow head at angle `deg` of a circle, pointing along the direction of travel."""
    a = math.radians(deg)
    px, py = cx + r * math.cos(a), cy + r * math.sin(a)
    tx, ty = -math.sin(a) * direction, math.cos(a) * direction
    nx, ny = -ty, tx
    tip = (px + tx * size * 0.6, py + ty * size * 0.6)
    return [(px - tx * size * 0.5 + nx * size * 0.6, py - ty * size * 0.5 + ny * size * 0.6), tip,
            (px - tx * size * 0.5 - nx * size * 0.6, py - ty * size * 0.5 - ny * size * 0.6)]


def _rays(cx, cy, r0, r1, n=8):
    return [("a", [(cx + r0 * math.cos(2 * math.pi * i / n), cy + r0 * math.sin(2 * math.pi * i / n)),
                   (cx + r1 * math.cos(2 * math.pi * i / n), cy + r1 * math.sin(2 * math.pi * i / n))]) for i in range(n)]


